import { BarList } from "march/charts"

// emoji anketi: bir satıra tıklamak o emojiye 250 oy ekler (bir sınıf dolusu), sıra hemen değişir
export function EmojiPoll() {
  let $votes = [{ label: "🔥", value: 1730 }, { label: "😂", value: 2410 }, { label: "🤔", value: 640 }, { label: "😍", value: 1980 }]
  return <BarList data={() => $votes} title="En sevilen emoji"
    onSelect={(r: { label: string; value: number; rank: number }) => { $votes = $votes.map((v) => (v.label === r.label ? { ...v, value: v.value + 250 } : v)) }} />
}

import { BarList } from "march/charts"
import { Card, Segmented } from "march/ui"

// bir sitenin en çok ziyaret edilen sayfaları: dönem seçilir, ilk beşi gösterilir; satıra tıklamak sayfayı açar gibi
const PAGES = {
  today: [{ yol: "/", ziyaret: 1840 }, { yol: "/fiyatlar", ziyaret: 920 }, { yol: "/blog/sinyaller-nedir-ve-neden-hizlidir", ziyaret: 610 }, { yol: "/iletisim", ziyaret: 240 }, { yol: "/kariyer", ziyaret: 120 }, { yol: "/yardim", ziyaret: 95 }],
  week: [{ yol: "/", ziyaret: 12400 }, { yol: "/blog/sinyaller-nedir-ve-neden-hizlidir", ziyaret: 8100 }, { yol: "/fiyatlar", ziyaret: 6300 }, { yol: "/yardim", ziyaret: 2100 }, { yol: "/iletisim", ziyaret: 1500 }, { yol: "/kariyer", ziyaret: 900 }],
}

export function TopPages() {
  let $range: "today" | "week" = "today"
  let $open = "—"
  return <Card title="En çok ziyaret edilenler" actions={[<Segmented size="sm" bind:value={$range} aria-label="Dönem" options={[{ value: "today", label: "Bugün" }, { value: "week", label: "Bu hafta" }]} />]}>
    <BarList data={() => PAGES[$range]} x="yol" y="ziyaret" limit={5} format="compact" color={1} title="Sayfalar" onSelect={(r: { label: string; value: number; rank: number }) => { $open = r.label }} />
    <p sx={{ text: "sm", color: "muted" }}>Açılan: {() => $open}</p>
  </Card>
}

import { test, expect, renderTest } from "march/testing"
import { BarListLab } from "./BarListLab.tsx"

// BarListLab'in testleri: kaydedince Testler sekmesinde çalışır
const labels = (el: Element) => [...el.querySelectorAll(".m-barlist-label")].map((l) => l.textContent)

test("sort={false}: veri sırası korunur; liste adıyla duyurulur", () => {
  const s = renderTest(() => <BarListLab />)
  const list = s.get(".lab-tasks")!
  expect(list.getAttribute("aria-label")).toBe("Görevler")
  expect(labels(list)).toEqual(["Tasarım", "Kod", "Test", "Yayın"])
})

test("onSelect satırları düğme yapar; tıklanan sırasıyla gelir", async () => {
  const s = renderTest(() => <BarListLab />)
  await s.click(s.all(".lab-tasks button")[1]!)
  expect(s.get(".lab-picked")!.textContent).toBe("Seçilen: 2. Kod")
})

test("limit ilk ikiyi gösterir; veri boşalınca boş metni", async () => {
  const s = renderTest(() => <BarListLab />)
  expect(labels(s.get(".lab-top")!)).toEqual(["Tasarım", "Kod"])
  await s.click(".lab-empty")
  expect(s.sees("Görev yok")).toBe(true)
})
